import uuid

def with_request_context(handler):
    def wrapped(request):
        request = {**request, 'request_id': str(uuid.uuid4())}
        if not request.get('learner_id'):
            return {'status': 401, 'error': 'authentication required'}
        return handler(request)
    return wrapped

@with_request_context
def create_export(request):
    job = {'job_id': 'job-42', 'state': 'queued', 'request_id': request['request_id']}
    return {'status': 202, 'job': job}

print(create_export({'learner_id': 'asha'}))

