def queue_export(request):
    if not request.get('learner_id'):
        return {'status': 401, 'error': 'authentication required'}
    job = {'job_id': 'job-1', 'state': 'queued'}
    return {'status': 202, 'job': job}

print(queue_export({}))
print(queue_export({'learner_id': 'asha'}))
